    #[test]
    fn redundant_typed_extension_recognizes_already_typed_sources() {
        assert!(super::is_redundant_typed_extension(
            IrOp::IntSext,
            PrimitiveType::Int(2),
            2,
            4,
        ));
        assert!(super::is_redundant_typed_extension(
            IrOp::IntZext,
            PrimitiveType::UnsignedInt(2),
            2,
            4,
        ));
        assert!(!super::is_redundant_typed_extension(
            IrOp::IntSext,
            PrimitiveType::UnsignedInt(2),
            2,
            4,
        ));
        assert!(!super::is_redundant_typed_extension(
            IrOp::IntSext,
            PrimitiveType::Int(4),
            2,
            4,
        ));
    }

