        // Simulate: this->__vftable->method_0(this)
        // CALLIND(fptr, this_arg) at VA 0x1000 where fptr=reg(0), this=reg(8)
        use unlace_ir::ssa::TargetSet;

        let fptr = reg(0, 8);
